 m=original()
 class Scope(m.Reader):
  def __init__(self):self.root=r.root;self.files={}
  def path(self,rel):return r.path(rel)
  def read(self,rel):
   data=r.read(rel);self.files[rel]={'sha256':hashlib.sha256(data).hexdigest(),'size':len(data)};return data
